declare(strict_types=1);
ini_set('display_errors','0');require dirname(__DIR__).'/private/app.php';require dirname(__DIR__).'/private/lifecycle/prospects.php';security_headers();header('Referrer-Policy: no-referrer');header('Cache-Control: private, no-store');header('X-Robots-Tag: noindex,nofollow');header('Content-Type: application/json; charset=utf-8');
try{
 $r=$_GET['r']??'';$method=$_SERVER['REQUEST_METHOD'];if(!is_string($r))crm_fail(404,'Не найдено.');
 if(($_GET['mode']??'')==='owner'){
  current_session($method!=='GET');crm_gate();lc_gate();rate('prospect-owner',100);
  if($method==='POST'){$d=input();if($r==='links')json_response(ps_create($d));if($r==='import')json_response(ps_import($d));if($r==='revoke'){$id=cc_id($d['id']??null);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите отзыв.');if(!crm_query('SELECT id FROM nd_lc_prospect_links WHERE id=?',[$id])->fetchColumn())crm_fail(404,'Ссылка не найдена.');crm_atomic(function()use($id){crm_query('UPDATE nd_lc_prospect_links SET revoked_at=COALESCE(revoked_at,?) WHERE id=?',[time(),$id]);ps_event($id,'owner','link_revoked');});json_response(['ok'=>true]);}}
  if($method==='GET'&&$r==='links'){$links=crm_query('SELECT id,order_id,scope_json,expires_at,revoked_at,created_at FROM nd_lc_prospect_links ORDER BY id DESC LIMIT 100')->fetchAll();$uploads=crm_query('SELECT id,link_id,binding_id,display_name,mime,size_bytes,checksum,imported_file_id,created_at FROM nd_lc_prospect_uploads ORDER BY id DESC LIMIT 100')->fetchAll();json_response(['ok'=>true,'links'=>$links,'uploads'=>$uploads]);}
  if($method==='GET'&&$r==='download'){$u=crm_query('SELECT * FROM nd_lc_prospect_uploads WHERE id=?',[cc_id(filter_var($_GET['id']??'',FILTER_VALIDATE_INT))])->fetch();if(!$u)crm_fail(404,'Копия не найдена.');$path=cc_file_path($u);header('Content-Type: '.$u['mime']);header('Content-Disposition: attachment; filename="signed-copy"; filename*=UTF-8\'\''.rawurlencode($u['display_name']));header('Content-Length: '.$u['size_bytes']);readfile($path);exit;}
  crm_fail(404,'Раздел не найден.');
