  $raw=bin2hex(random_bytes(32));$csrf=bin2hex(random_bytes(32));$expiry=min((int)$l['expires_at'],time()+3600);crm_query('INSERT INTO nd_lc_prospect_sessions(token_hash,link_id,csrf_hash,expires_at) VALUES (?,?,?,?)',[hash('sha256',$raw),$l['id'],hash('sha256',$csrf),$expiry]);setcookie(ps_cookie_name(),$raw,['expires'=>$expiry,'path'=>'/','secure'=>parse_url(config()['app_url'],PHP_URL_SCHEME)==='https','httponly'=>true,'samesite'=>'Strict']);ps_event((int)$l['id'],'prospect','link_opened',['identity_verified'=>false]);json_response(['ok'=>true,'csrf'=>$csrf,'consent_required'=>true,'policy'=>['version'=>$p['version'],'url'=>$p['url'],'consent_url'=>$p['consent_url']]]);
